/* Iteración 02. Presentaciones aprobadas; simulación local de los refinamientos. */
(()=>{
'use strict';
const old={load:loadScenario,render,phone,body,sheetContent,sheetFooter,sheetTitle,sheet,action:onAction,commit:commitRecord,header,inline:inlineEditor,row:rowMarkup,list:sessionList,inspector,media:mediaContent};
let listControls='inline', warmPage=0;
const oldAdjacent=adjacent;
adjacent=function(delta){if(state.scene!=='superset')return oldAdjacent(delta);const rows=Array.from({length:state.superRounds||3},(_,round)=>state.exercises.slice(0,2).map((e,ei)=>({ei,id:e.sets.filter(s=>s.kind==='working')[round]?.id}))).flat().filter(r=>r.id);const target=rows[rows.findIndex(r=>r.id===state.selected)+delta];if(target)selectRow(target.id,target.ei);else notify('Fin de la superserie.');};
const addScene=(id,label,group,detail)=>scenarios.push([id,label,group,detail]);
[
 ['rest-card','Descanso · tarjeta','Descanso','La misma tarjeta; ampliar conserva el reloj.'],
 ['rest-suggested','Descanso · sugerencia','Descanso','Comparar el tiempo planificado y el sugerido.'],
 ['rest-feedback','Descanso · feedback','Descanso','Técnica y molestias del ejercicio terminado.'],
 ['rest-feedback-full','Feedback · pantalla completa','Descanso','Mismo borrador en ambas presentaciones.'],
 ['games','Minijuegos · selector','Descanso','Tres juegos que comparten el reloj del descanso.'],
 ['game-runner','Juego · Salta las mancuernas','Descanso','Obstáculos, combinaciones y suplementos.'],
 ['game-flappy','Juego · Entre las pesas','Descanso','Pasos precisos y cadenas de aciertos.'],
 ['game-shooter','Juego · Escuadrón retro','Descanso','Oleadas, disparos automáticos y esquiva.'],
 ['tags','Etiquetas · contexto por ejercicio','Contexto','Seleccionar contexto sin modificar registros anteriores.'],
 ['tag-setup','Etiqueta · setup e historial','Contexto','Equipo, carga base y notas del contexto.'],
 ['set-config','Configurar serie','Contexto','Editar objetivos separados del registro realizado.'],
 ['replacement','Reemplazo · elegir','Contexto','Revisar lo que se conserva antes de reemplazar.'],
 ['replacement-preview','Reemplazo · revisar','Contexto','Plan heredado, carga y contexto independientes.'],
 ['alert-effort','Aviso · falta esfuerzo','Avisos','Validación junto al campo.'],
 ['alert-discomfort','Aviso · molestia reportada','Avisos','Información contextual del historial.'],
 ['alert-save','Aviso · error de guardado','Avisos','Reintentar sin perder el borrador.'],
 ['alert-conflict','Aviso · sesión en curso','Avisos','Reanudar o revisar el descarte.'],
 ['video-detail','Vídeo · análisis detallado','Medios','Trayectorias, reproducción, métricas y repeticiones.'],
 ['voice-picker','Voz · selector compacto','Voz','Música o manos libres; prueba de «Listo».'],
 ['voice-conversation','Voz · conversación y registros','Voz','Trazabilidad, revisión y corrección por captura.'],
 ['voice-review','Voz · captura por revisar','Voz','Ambigüedad visible antes de registrar.']
].forEach(x=>addScene(...x));
addScene('framing','Captura · encuadre y voz','Medios','Guía hablada independiente y comandos de grabación.');
addScene('framing-warning','Captura · corregir encuadre','Medios','Avisos concretos antes de grabar.');
addScene('relator-context','Relator · asistencia contextual','Contexto','Explicaciones junto a la acción que ayudan a decidir.');
const activeTag=()=>ex().tags?.[0]||'Sin etiqueta';
const rr=()=>state.rest;
function enrich(){
 if(state.revision!==2){state.revision=2;state.alert=null;state.fullSurface=null;state.restPanel='clock';state.feedbackDraft={quality:7,discomforts:[],previous:'pending',saved:false};state.analysisTab='replay';state.analysisPartial=[9,10];state.analysisRep=3;state.analysisFrame=25;state.analysisLayers=['bar','body'];state.analysisMetric='ROM';state.analysisPlaying=false;state.voiceStep='choices';state.voiceVerified=false;state.voiceFilter='all';state.voicePaused=false;state.voiceEvents=[{id:1,time:'38:05',said:'100 kilos, ocho repeticiones, RIR dos',weight:'100',reps:'8',effort:'2',status:'registered',set:'sq2',exercise:0,version:1},{id:2,time:'38:24',said:'Cien kilos, ocho… o seis repeticiones',weight:'100',reps:'6',effort:'',status:'review',set:'sq3',exercise:0,version:1}];state.voiceEdit=null;state.configTab='target';state.tagForm=null;state.replaceChoice='Sentadilla Frontal';state.suggestionApplied=false;warmPage=0;}
 rr().presentation??='card';rr().suggested??=150;rr().plan??=120;
 state.exercises.forEach((e,i)=>{e.tags??=[];e.tagOptions??=['Competición','Tempo','Sin cinturón'];e.contexts??=Object.fromEntries(e.tagOptions.map((t,n)=>[t,{name:t,brand:n===0?'Barra olímpica':'',base:'20',notes:n===1?'Descenso controlado de 3 segundos':'',previous:n===1?'80 × 8 · RIR 2':e.previous,weight:n===1?'80':i===0?'100':i===1?'140':'214'}]));e.sets.forEach(s=>{s.recordTag??=s.status==='done'?(e.tags[0]||'Sin etiqueta'):null;s.plan??={min:'6',max:'8',rest:'120',effort:'2',mode:'RIR',unit:s.unit,purpose:'Efectiva',load:s.loadType};});});
}
loadScenario=function(id){old.load(id);enrich();warmPage=0;state.fullSurface=null;state.alert=null;state.restPanel='clock';
 if(id==='superset'){state.superRounds=3;state.superBetween=20;state.superAfter=120;state.exercises=state.exercises.slice(0,2);state.exercises.forEach((e,ei)=>{e.short=ei?'Curl femoral':'Extensiones';e.equipment='Máquina';e.previous=(ei?40:45)+' × 12 · RIR 2';e.sets=e.sets.filter(s=>s.kind==='working').slice(0,3);e.sets.forEach((s,i)=>Object.assign(s,{label:String(i+1),weight:ei?'40':'45',value:'12',status:i===0?'done':'pending',effort:i===0?2:null}));});state.ex=0;state.selected=state.exercises[0].sets[1].id;state.openRow=state.selected;}
 if(id==='rest')rr().presentation='full';
 if(['rest-card','rest-suggested','rest-feedback','rest-feedback-full','games','game-runner','game-flappy','game-shooter'].includes(id)){state.phase='rest';Object.assign(rr(),{active:true,seconds:92,total:120,running:true,presentation:id==='rest-feedback-full'?'full':'card'});}
 if(id==='rest-suggested')state.sheet='rest-suggestion';
 if(id==='rest-feedback'||id==='rest-feedback-full'||id==='feedback'){state.phase='rest';state.restPanel='feedback';rr().active=true;rr().running=true;state.feedbackExercise=0;}
 if(id==='games')state.restPanel='picker';
 if(id.startsWith('game-')){state.restPanel='game';state.arcadeMode=id.slice(5);window.KpknArcade?.start(state.arcadeMode);}
 if(id==='tags')state.sheet='tags';if(id==='tag-setup'){state.tagOriginal='Competición';state.tagForm={...ex().contexts.Competición};state.sheet='tag-setup';}
 if(id==='set-config'){startConfig();state.sheet='set-config';}
 if(id==='replacement')state.sheet='replace';if(id==='replacement-preview')state.sheet='replace-preview';
 if(id==='alert-effort')state.error='Marca tu esfuerzo antes de registrar.';
 if(id.startsWith('alert-')&&id!=='alert-effort')state.alert=id.slice(6);
 if(id==='video-detail')state.fullSurface='analysis';
 if(id==='voice-picker'){state.sheet='voice';state.voiceStep='choices';}
 if(id==='voice-conversation'||id==='voice-review'){state.voice=true;state.fullSurface='voice';if(id==='voice-review')state.voiceFilter='review';}
 if(id.startsWith('framing')){state.fullSurface='capture';state.framing=id==='framing-warning'?'feet':'ok';state.spokenGuide=false;state.captureVoice=state.voice;}
 if(id==='relator-context')state.sheet='assistance';
 render();
};
render=function(){enrich();if(view==='focus')view='list';old.render();$$('.phone').forEach(p=>{const modal=p.querySelector(':scope > .v2-alert-backdrop')||p.querySelector(':scope > .sheet-backdrop')||p.querySelector(':scope > .v2-fullscreen');Array.from(p.children).forEach(e=>e.inert=!!modal&&e!==modal&&!e.classList.contains('toast'));});document.documentElement.classList.toggle('list-inline',listControls==='inline');updateEclipse();updateAnalysis();};
function slotCard(label,body,footer='',cls=''){
 return `<section class="set-card v2-card ${cls}" aria-label="${esc(label)}"><div class="v2-content">${body}</div>${footer?`<div class="v2-card-footer">${footer}</div>`:''}</section>`;
}
function cardTop(left,right=''){return `<div class="v2-kicker"><span>${left}</span>${right}</div>`;}
function contextSummary(){const r=row();return [r.partials?`+${r.partials} parciales`:null,r.assisted?`${r.assisted} con ayuda`:null,state.showRom?`ROM ${r.rom}%`:null].filter(Boolean).join(' · ')||'Parciales, ayuda y ROM';}
frontCard=function(){const r=row(),quantity=r.unit==='reps'?'REPETICIONES':r.unit==='s'?'TIEMPO':r.unit==='m'?'DISTANCIA':r.unit.toUpperCase();
 const context=state.scene==='rm'?`${state.percent}% · RM ${state.rm} kg`:['Corporal','Lastre','Asistida'].includes(r.loadType)?`${r.loadType} · corporal ${state.bodyWeight} kg`:state.history?ex().previous:'Sin historial anterior';
 const side=state.scene==='unilateral'?btn('side',r.side==='L'?'Izquierda':'Derecha','v2-side',`data-side="${r.side==='L'?'R':'L'}"`):'';
 const body=cardTop(`${state.purpose||(state.scene==='superset'?'RONDA '+r.label+' · A'+(state.ex+1):'SERIE '+r.label)} <span class="dim">/ ${ex().sets.filter(s=>s.kind==='working').length}</span>`,`${side}${ib('v2-config','tune','Configurar esta serie')}`)+
 `<div class="v2-load"><div class="field-heading"><span>${r.loadType==='Asistida'?'AYUDA EXTERNA':r.loadType==='Lastre'?'LASTRE':'CARGA'}</span>${open('load',esc(r.loadType)+icon('down',12))}</div><div class="hero-edit"><div class="metric-wrap">${fieldInput('weight',r.weight,'metric-input','Carga en kg','placeholder="—"')}<span class="unit">kg</span></div>${adjustButtons('weight',2.5)}</div><div class="v2-reference"><span>${esc(context)}</span>${open(state.scene==='rm'?'rm':'history',icon('history',14),'','aria-label="Consultar referencia"')}</div></div>`+
 `<div class="v2-quantity"><div class="field-heading"><span>${quantity}</span>${r.unit==='s'?btn('set-clock',`${icon(state.setRunning?'pause':'play',13)} <span data-clock="set">${clock(state.setClock)}</span>`):state.purpose?`<span class="dim">${state.purpose==='Calibrador'?'0 reps permitido':'Mínimo 6'}</span>`:''}</div>${r.unit==='reps'?`<div class="wheel-track">${[-2,-1,0,1,2].map(d=>btn('qty',Math.max(0,num(r.value)+d),d===0?'current':'',`data-value="${Math.max(0,num(r.value)+d)}" aria-label="${Math.max(0,num(r.value)+d)} repeticiones"`)).join('')}</div>`:`<div class="v2-quantity-input">${fieldInput('value',r.value,'metric-input','Cantidad registrada')}<span>${r.unit}</span>${adjustButtons('value',1)}</div>`}</div>`+
 effortBlock()+`<div class="v2-detail-line">${state.error?`<span class="v2-inline-error" role="alert">${esc(state.error)}</span>`:open('v2-details',contextSummary()+icon('right',12),'v2-detail-button')}</div>`;
 if(r.status==='failed')return slotCard('Serie con incidencia',cardTop('SERIE '+r.label)+`<div class="v2-failure"><div class="failure-mark">!</div><h3>Error de ejecución</h3><p>${r.weight} kg × ${r.value}<br>El fallo muscular se registra en esfuerzo.</p>${open('failure-detail','Revisar motivo','secondary full')}${btn('revert-failed','Recuperar serie','primary full')}</div>`,actions());
 return slotCard('Tarjeta de serie',body,actions());
};
advancedCard=function(){const r=row(),seg=r.segments[state.techSegment-1];return slotCard('Detalle avanzado',cardTop(btn('face',icon('left',14)+' Serie '+r.label,'','data-face="front"'),'<span>AVANZADO</span>')+
 `<div class="v2-tech-tabs">${[['normal','Normal'],['drop','Drop'],['pause','Rest-pause'],['myo','Myo']].map(([id,label])=>btn('tech',label,r.technique===id?'selected':'',`data-value="${id}"`)).join('')}</div>`+
 `<div class="v2-chain-head"><span>CADENA DE LA SERIE</span>${open('tech-chain',`${r.segments.length+1} tramos ${icon('right',12)}`)}</div><div class="v2-segment-switch">${btn('v2-segment-prev',icon('left',16),'',`aria-label="Tramo anterior" ${state.techSegment===0?'disabled':''}`)}<div><small>${state.techSegment===0?'PRINCIPAL':(r.technique==='drop'?'DROP':'TRAMO')+' '+state.techSegment}</small><strong>${seg?seg.weight+' × '+seg.reps:r.weight+' × '+r.value}</strong></div>${btn('v2-segment-next',icon('right',16),'',`aria-label="Tramo siguiente" ${state.techSegment>=r.segments.length?'disabled':''}`)}</div>`+
 (seg?`<div class="two-fields v2-fields"><label class="input-label">${r.technique==='drop'?'Carga · kg':'Pausa · s'}${fieldInput(r.technique==='drop'?'segment-weight':'segment-seconds',r.technique==='drop'?seg.weight:seg.seconds,'','Valor del tramo')}</label><label class="input-label">Repeticiones${fieldInput('segment-reps',seg.reps,'','Reps del tramo')}</label></div>`:`<p class="v2-short-copy">Carga, repeticiones y esfuerzo de la serie principal se conservan.</p>`)+
 `<div class="v2-advanced-links">${open('series-note',`${icon('note',16)} ${r.note?'Ver nota':'Añadir nota'} ${icon('right',12)}`,'v2-detail-button')}${r.technique!=='normal'?btn('v2-add-segment',icon('plus',15)+' Añadir tramo','v2-detail-button',r.segments.length>=5?'disabled':''):''}${open('failure-detail','Error de ejecución','v2-detail-button danger')}</div>`,btn('face','Volver al registro','secondary full','data-face="front"'));
};
mediaCard=function(){return slotCard('Modo visual',cardTop(btn('face',icon('left',14)+' Serie '+row().label,'','data-face="front"'),open('album','Álbum'))+
 `<div class="v2-media-preview"><img src="${EXERCISE_ART}" alt="Ilustración KPKN de demostración"><div class="v2-media-top">${btn('media-mode',state.mediaMode==='video'?'Vídeo':'Foto')}${open('exercise-info','Ficha')}</div>${btn('capture',state.recording?'<i></i>':'',`capture-button ${state.recording?'recording':''}`,`aria-label="${state.recording?'Detener vídeo de demostración':'Capturar demostración'}"`)}<span class="v2-media-badge">${state.recording?'Grabando demo':'Cámara · demo'}</span></div>`+
 `<div class="v2-media-summary"><span>${state.analysis==='working'?'Analizando…':state.analysis==='low'?'Requiere revisión':'8 completas · 2 parciales'}</span>${btn('v2-analysis','Abrir análisis '+icon('right',13))}</div>`,btn('v2-analysis',icon('route',16)+' Revisar trayectoria y métricas','secondary full'));
};
mobilityCard=function(){const names=['Movilidad de tobillo','Apertura de cadera','Sentadilla sin carga'];let content='';
 if(state.mobilityView==='list')content=names.map((n,i)=>`<div class="v2-movement-row">${btn('mobility-check',`<span class="check-circle ${state.mobility[i]?'checked':''}">${state.mobility[i]?icon('check',12):''}</span><span>${n}</span>`,'',`data-index="${i}"`)}${btn('v2-movement',icon('info',15),'',`data-index="${i}" aria-label="Detalle de ${n}"`)}</div>`).join('');
 if(state.mobilityView==='move')content=`<img class="v2-movement-art" src="${EXERCISE_ART}" alt="Demostración de movimiento"><div class="v2-movement-caption">Sentadilla sin carga ${btn('v2-movement','Ver guía '+icon('right',12),'','data-index="2"')}</div>`;
 if(state.mobilityView==='global')content=`<p class="v2-short-copy">Articulaciones del movimiento.</p><div class="v2-joints">${['Tobillo','Rodilla','Cadera','Columna'].map(t=>btn('joint',t+icon('right',13),'',`data-value="${t}"`)).join('')}</div>`;
 return slotCard('Tarjeta de movilidad',cardTop('MOVILIDAD',`${state.mobility.filter(Boolean).length} / 3`)+`<h3 class="v2-card-title">Prepara el movimiento.</h3><div class="v2-tech-tabs">${[['list','Checklist'],['move','Movimiento'],['global','Articulaciones']].map(([id,t])=>btn('mobility-view',t,state.mobilityView===id?'selected':'',`data-value="${id}"`)).join('')}</div><div class="v2-prep-main">${content}</div>`,`<div class="v2-split-actions">${btn('prep-skip','Omitir','secondary')}${btn('prep-done','Continuar','primary')}</div>`);
};
warmupCard=function(){const rows=ex().sets.filter(s=>s.kind==='warmup');warmPage=Math.min(warmPage,Math.max(0,Math.ceil(rows.length/3)-1));return slotCard('Tarjeta de aproximaciones',cardTop('APROXIMACIONES',`${rows.filter(s=>s.status==='done').length} / ${rows.length}`)+`<h3 class="v2-card-title">Acércate a tu carga.</h3><div class="v2-reference"><span>Trabajo · ${row().weight||100} kg</span>${open('warmup-load','Ajustar')}</div><div class="v2-warm-rows">${rows.slice(warmPage*3,warmPage*3+3).map((s,i)=>warmRow(s,i)).join('')}</div><div class="v2-warm-footer">${btn('warmup-add',icon('plus',14)+' Aproximación')}${rows.length>3?`<div>${btn('v2-warm-page',icon('left',13),'','data-direction="-1" aria-label="Página anterior"')}<span>${warmPage+1}/${Math.ceil(rows.length/3)}</span>${btn('v2-warm-page',icon('right',13),'','data-direction="1" aria-label="Página siguiente"')}</div>`:''}</div>`,`<div class="v2-split-actions">${btn('prep-skip','Omitir','secondary')}${btn('prep-done','Ir a efectivas','primary')}</div>`);};
function warmRow(s,i){return `<div class="v2-warm-row"><small>${s.label}</small><span>${Math.round(num(s.weight)/num(row().weight||100)*100)} %</span><strong>${esc(s.weight)} × ${esc(s.value)}</strong>${btn('warmup-check',s.status==='done'?icon('check',16):icon('plus',15),'',`data-id="${s.id}" aria-label="${s.status==='done'?'Desmarcar':'Completar'} aproximación ${s.label}"`)}</div>`;}
cardioCard=function(){return slotCard('Tarjeta de cardio',cardTop(state.cardioIntervals?'INTERVALOS · '+(state.cardioBlock+1)+'/8':'CARDIO',state.cardioRunning?'En curso':'Pausado')+`<div class="v2-cardio-clock" data-clock="cardio">${clock(state.cardioSeconds)}</div><div class="v2-centered dim">${state.cardioIntervals?'Esfuerzo · 2:00 / recuperación · 1:00':'Objetivo · 20:00'}</div><div class="v2-interval-bars">${Array.from({length:8},(_,i)=>`<i class="${i===state.cardioBlock?'active':''}"></i>`).join('')}</div><div class="v2-cardio-metrics"><div><strong>1,42</strong><small>km · demo</small></div><div><strong>5′43″</strong><small>/km · demo</small></div><div><strong>—</strong><small>FC</small></div></div>${open('cardio-details','Distancia y notas '+icon('right',13),'v2-detail-button')}`,`<div class="v2-split-actions">${btn('cardio-toggle',state.cardioRunning?'Pausar':'Continuar','secondary')}${state.cardioIntervals?btn('cardio-next','Siguiente bloque','primary'):btn('record','Registrar cardio','primary')}</div>`);};
resultCard=function(){return slotCard('Resultado de calibración',cardTop('CALIBRACIÓN','Registrada')+`<div class="v2-calibration"><small>RESULTADO</small><strong>${row().value}<span> reps</span></strong><p>${row().weight} kg · ${effortLabel(row())}</p><h3>102,5 kg</h3><p>Propuesta de ejemplo para las series pendientes.</p>${btn('calibration-keep','Mantener el plan','secondary full')}${btn('calibration-edit','Corregir registro','text-action')}</div>`,btn('calibration-apply','Aplicar propuesta','primary full'));};
function eclipse(size=''){const progress=Math.max(0,Math.min(1,(rr().total-rr().seconds)/rr().total));return `<div class="eclipse ${size}" style="--progress:${progress};--turn:${progress*360}deg"><svg viewBox="0 0 200 200" aria-hidden="true"><circle class="eclipse-track" cx="100" cy="100" r="88"/><circle class="eclipse-corona" cx="100" cy="100" r="88" pathLength="100"/><circle class="eclipse-progress" cx="100" cy="100" r="88" pathLength="100"/></svg><span class="eclipse-pearl"></span><div class="eclipse-center"><strong data-clock="rest">${rr().seconds<0?'+':''}${clock(rr().seconds)}</strong><span>${rr().seconds<0?'Tiempo extra':rr().running?'Descansando':'En pausa'}</span></div></div>`;}
function clockControls(){return `<div class="v2-rest-controls">${btn('rest-adjust','−15 s','','data-amount="-15"')}${btn('rest-pause',icon(rr().running?'pause':'play',18),'',`aria-label="${rr().running?'Pausar':'Continuar'} descanso"`)}${btn('rest-adjust','+15 s','','data-amount="15"')}</div>`;}
function suggestion(){return open('rest-suggestion',`<span>${state.suggestionApplied?'Sugerido aplicado':'Descanso sugerido'}</span><strong>${clock(rr().suggested)}</strong>${icon('right',13)}`,'v2-suggestion');}
function feedbackMarkup(full=false){const d=state.feedbackDraft,e=state.exercises[state.feedbackExercise??state.ex];return `<div class="v2-feedback ${full?'wide':''}"><div class="v2-feedback-heading"><div><small>EJERCICIO TERMINADO</small><h3>${esc(e.short)}</h3></div><div class="v2-quality-figure">${icon('flame',28)}</div></div><div class="v2-feedback-score"><span>Calidad técnica</span><strong>${d.quality}<small>/10</small></strong></div><input class="v2-quality-range" type="range" min="1" max="10" value="${d.quality}" data-v2="quality" aria-label="Calidad técnica"><div class="v2-quality-labels"><span>Por mejorar</span><span>Muy buena</span></div><div class="v2-feedback-discomfort">${open('feedback-discomforts',`<span>Molestias</span><strong>${d.discomforts.length?d.discomforts.join(', '):'Sin seleccionar'}</strong>${icon('right',12)}`)}</div><div class="v2-linked-feedback"><span>Rodilla · reportada antes</span><div>${btn('v2-previous','Sigue',d.previous==='present'?'selected':'','data-value="present"')}${btn('v2-previous','Se resolvió',d.previous==='resolved'?'selected':'','data-value="resolved"')}</div></div>${full?'<p class="v2-short-copy">El reloj continúa mientras registras cómo salió el ejercicio.</p>':''}</div>`;}
function arcadeHeader(){return `<div class="v2-arcade-header">${btn('v2-rest-panel',icon('left',15),'','data-value="clock" aria-label="Volver al descanso"')}<span>${state.restPanel==='picker'?'Jugar mientras descansas':({runner:'Salta las mancuernas',flappy:'Entre las pesas',shooter:'Escuadrón retro'})[state.arcadeMode]}</span><strong data-clock="rest">${clock(rr().seconds)}</strong></div>`;}
function gamePicker(){return `<div class="v2-game-picker">${[['runner','Salta las mancuernas','Rachas, saltos y suplementos','↗'],['flappy','Entre las pesas','Encuentra el hueco perfecto','◉'],['shooter','Escuadrón retro','Esquiva las oleadas','⌁']].map(([id,title,hint,symbol],i)=>btn('v2-game',`<div class="v2-game-art game-${id}"><span>${symbol}</span><i></i><b>0${i+1}</b></div><div><strong>${title}</strong><small>${hint}</small></div>${icon('right',13)}`,'',`data-value="${id}"`)).join('')}</div>`;}
function gameArena(){return `<div class="v2-game-arena"><canvas class="game-canvas" width="720" height="520" tabindex="0" aria-label="${state.arcadeMode==='runner'?'Toca o pulsa Espacio para saltar':state.arcadeMode==='flappy'?'Toca o pulsa Espacio para volar':'Arrastra o usa las flechas para mover la nave'}"></canvas><div class="v2-game-start">${btn('v2-game-start','Empezar','primary')}</div><div class="v2-game-result" hidden><strong>Fin de partida</strong><span></span>${btn('v2-game-restart','Volver a jugar','primary')}</div></div><div class="v2-game-hud"><span data-game-score>0 puntos</span><span data-game-combo>Racha ×1</span><span data-game-lives>3 vidas</span></div>`;}
function gameControls(){return `<div class="v2-game-controls">${btn('v2-game-restart',icon('undo',14),'','aria-label="Reiniciar juego"')}${btn('v2-game-input',state.arcadeMode==='runner'?'Saltar':state.arcadeMode==='flappy'?'Volar':'← Mover →','primary')}${btn('v2-rest-panel','Otro juego','','data-value="picker"')}</div>`;}
restCard=function(){const r=rr();let content='',footer='';
 if(state.restPanel==='picker'){content=arcadeHeader()+gamePicker();footer=btn('v2-rest-panel','Volver al descanso','secondary full','data-value="clock"');}
 else if(state.restPanel==='game'){content=arcadeHeader()+gameArena();footer=gameControls();}
 else if(state.restPanel==='feedback'){content=cardTop(`<span data-clock="rest">${clock(r.seconds)}</span> · DESCANSO`,ib('v2-rest-full','expand','Expandir descanso'))+feedbackMarkup();footer=`<div class="v2-split-actions">${btn('v2-feedback-skip','Ahora no','secondary')}${btn('v2-feedback-save','Guardar feedback','primary')}</div>`;}
 else {content=cardTop(state.scene==='warmup-rest'?'DESCANSO · APROX.':'DESCANSO',ib('v2-rest-full','expand','Expandir descanso'))+eclipse()+clockControls()+`<div class="v2-rest-next"><small>SIGUIENTE</small><strong>${esc(ex().short)} · serie ${row().label}</strong><span>${row().weight||'—'} kg × ${row().value}</span></div>`+suggestion();footer=btn('v2-rest-panel',`${icon('play',15)} Jugar mientras descansas`,'secondary full','data-value="picker"');}
 return slotCard('Tarjeta de descanso',content,footer,'v2-rest-card '+(state.restPanel==='game'?'game-host':''));
};
feedbackCard=()=>restCard();
function restFullscreen(){if(state.phase!=='rest'||rr().presentation!=='full')return '';const panel=state.restPanel;return `<section class="v2-fullscreen rest-fullscreen" aria-label="Descanso a pantalla completa">${statusbar()}<div class="v2-full-top"><div><small>${panel==='feedback'?'DESCANSO + FEEDBACK':'PAUSA ENTRE SERIES'}</small><strong>${esc(ex().short)}</strong></div>${btn('v2-rest-card',icon('down',18),'icon-btn','aria-label="Minimizar a tarjeta"')}</div><div class="v2-rest-full-main ${panel==='game'?'game-host':''}">${panel==='clock'?`<div class="v2-rest-note">${rr().seconds<0?'Tu descanso se ha cumplido.':'Una pausa antes de la siguiente.'}</div>${eclipse('full')}${clockControls()}${suggestion()}<div class="v2-rest-full-context"><div><small>ÚLTIMA</small><strong>${rr().lastSet||'100 × 8 · RIR 2'}</strong></div><div><small>SIGUIENTE</small><strong>${esc(ex().short)} · ${row().label}</strong><span>${row().weight} kg × ${row().value}</span></div></div>${btn('v2-rest-panel',icon('play',17)+' Jugar mientras descansas','v2-full-game-link','data-value="picker"')}`:panel==='feedback'?`<div class="v2-feedback-clock">${eclipse('tiny')}<div><strong data-clock="rest">${clock(rr().seconds)}</strong><small>de ${clock(rr().total)} · el reloj sigue</small></div>${open('rest-suggestion',clock(rr().suggested)+' sugerido')}</div>${feedbackMarkup(true)}<div class="v2-split-actions">${btn('v2-feedback-skip','Ahora no','secondary')}${btn('v2-feedback-save','Guardar feedback','primary')}</div>`:arcadeHeader()+(panel==='picker'?gamePicker():gameArena()+gameControls())}</div><div class="v2-full-bottom">${rr().seconds<=0?btn('rest-adjust','Necesito +30 s','secondary full','data-amount="30"'):''}${btn('v2-rest-end',rr().seconds<=0?'Continuar entrenando':'Terminar descanso','primary full')}</div><div class="home-indicator"></div></section>`;}
function compactPreparation(){const mobility=state.phase==='mobility',names=['Movilidad de tobillo','Apertura de cadera','Sentadilla sin carga'];return `<section class="v2-prep-list"><div class="v2-prep-list-heading"><div><small>PREPARACIÓN</small><strong>${mobility?'Movilidad':'Aproximaciones'}</strong></div><span>${mobility?state.mobility.filter(Boolean).length+' / 3':ex().sets.filter(s=>s.kind==='warmup'&&s.status==='done').length+' / '+ex().sets.filter(s=>s.kind==='warmup').length}</span></div>${mobility?names.map((t,i)=>`<div class="v2-prep-list-row"><span class="dim">0${i+1}</span>${btn('v2-movement',t,'',`data-index="${i}"`)}${btn('mobility-check',state.mobility[i]?icon('check',16):icon('plus',16),'',`data-index="${i}" aria-label="Completar ${t}"`)}</div>`).join(''):ex().sets.filter(s=>s.kind==='warmup').map(warmRow).join('')}<div class="v2-prep-list-actions">${mobility?btn('mobility-view','Articulaciones','','data-value="global"'):open('warmup-load','Referencia · '+(row().weight||100)+' kg')}${btn('prep-done',mobility?'Aproximaciones →':'Ir a efectivas →')}</div></section>`;}
body=function(which){if(which==='list'&&['mobility','warmup'].includes(state.phase))return `<div class="body-region"><div class="list-area" data-scroll="list">${compactPreparation()}<div class="list-intro"><span>SERIES EFECTIVAS</span><span>${doneCount()} / ${workSets().length}</span></div>${sessionList()}</div></div>`;let html=old.body(which);html=html.replace(/<div class="rest-mini">[\s\S]*?<\/div>/,'');return html;};
rowMarkup=function(e,r,ei){let html=old.row(e,r,ei);if(listControls==='inline'&&r.kind==='working'){html=html.replace(/<button type="button" class="row-state[\s\S]*?<\/button>/,btn('v2-row-record',r.status==='done'?icon('tune',13):icon('check',14),'v2-row-register '+(r.status==='done'?'recorded':''),`data-id="${r.id}" data-ex="${ei}" aria-label="${r.status==='done'?'Editar':'Registrar'} serie ${r.label} de ${esc(e.name)}"`));}return html;};
inlineEditor=function(){return old.inline()+(listControls==='inline'?btn('record',icon('check',15)+(row().status==='done'?'Actualizar':'Registrar')+' serie '+row().label,'v2-inline-register primary full'):'');};
sessionList=function(editable=true){if(state.scene!=='superset')return old.list(editable);const exercises=state.exercises.slice(0,2);return `<section class="v2-superset"><div class="v2-super-head"><div><small>SUPERSERIE A</small><strong>Extensión + curl femoral</strong></div>${open('superset-settings',icon('tune',16),'icon-btn','aria-label="Configurar superserie"')}</div><div class="v2-super-plan"><span>${state.superRounds||3} rondas</span><span>Entre ejercicios · ${state.superBetween??20} s</span><span>Tras ronda · ${clock(state.superAfter??120)}</span></div>${Array.from({length:state.superRounds||3},(_,i)=>i).map(round=>`<div class="v2-round"><div class="v2-round-label"><span>RONDA ${round+1}</span><i></i></div>${exercises.map((e,ei)=>{const r=e.sets.filter(s=>s.kind==='working')[round];return r?`<div class="v2-super-exercise"><div class="v2-super-name"><b>A${ei+1}</b><span>${e.name}</span></div>${rowMarkup(e,r,ei)}${editable&&state.selected===r.id&&state.openRow===r.id?inlineEditor():''}</div>`:'';}).join('')}</div>`).join('')}</section>`;};
header=function(){return old.header().replace('data-action="voice"','data-action="v2-voice"');};
phone=function(which){let html=old.phone(which);if(which==='list'){
 const start=html.indexOf('<div class="context">'),end=html.indexOf('<div class="body-region">',start);if(start>=0&&end>start){const context=html.slice(start,end);html=html.slice(0,start)+html.slice(end);html=html.replace(/(<div class="list-area"[^>]*>)/,'$1'+context);}
 if(listControls==='inline'){html=html.replace(/<footer class="dock">[\s\S]*?<\/footer>/,'');if(state.phase==='rest')html=html.replace('<div class="home-indicator">',`${btn('v2-rest-end','Terminar descanso','v2-list-rest-end primary')}<div class="home-indicator">`);}
 }
 const overlays=restFullscreen()+fullSurface()+alertOverlay();return html.replace(/<\/div><\/div><\/div>$/,overlays+'</div></div></div>');};
inspector=function(which){let html=old.inspector(which);const extra=`<div class="v2-review-shortcuts"><div class="eyebrow">REFINAMIENTOS 02</div>${[['rest-card','Descanso · tarjeta'],['rest','Descanso · completo'],['rest-feedback','Feedback en descanso'],['games','Minijuegos'],['tags','Etiquetas y setup'],['set-config','Configuración de serie'],['replacement','Reemplazos'],['video-detail','Análisis detallado'],['voice-conversation','Conversación de voz']].map(([id,t])=>btn('scene',t+icon('right',12),'',`data-value="${id}"`)).join('')}${which==='list'?`<div class="eyebrow">REGISTRO EN LISTA</div><div class="segmented">${btn('v2-list-controls','En cada serie',listControls==='inline'?'selected':'','data-value="inline"')}${btn('v2-list-controls','Roadmap',listControls==='dock'?'selected':'','data-value="dock"')}</div><p>Alternativas del refinamiento. El botón por serie deja más espacio al registro.</p>`:''}</div>`;return html.replace('</aside>',extra+'</aside>').replace('ABIERTA A REVISIÓN','DIRECCIÓN APROBADA');};
function startConfig(){state.configDraft=structuredClone(row().plan);state.configScope='one';state.configDirty=false;state.configTab='target';}
function fullSurface(){return state.fullSurface==='analysis'?analysisSurface():state.fullSurface==='voice'?voiceSurface():state.fullSurface==='capture'?captureSurface():'';}
function updateEclipse(){const p=Math.max(0,Math.min(1,(rr().total-rr().seconds)/Math.max(1,rr().total)));$$('.eclipse').forEach(e=>{e.style.setProperty('--progress',p);e.style.setProperty('--turn',p*360+'deg');});}
// Additional panels, analysis and voice surfaces are defined below in this same scope.
const panelNames={'v2-details':'Detalle del registro','series-note':'Nota de la serie','failure-detail':'Error de ejecución','tech-chain':'Cadena de la serie','rest-suggestion':'Descanso sugerido','feedback-discomforts':'Molestias del ejercicio','movement-detail':'Movimiento','set-config':'Configurar serie','tag-setup':'Contexto del ejercicio','tag-new':'Nueva etiqueta','tag-change':'Cambiar contexto','replace-preview':'Revisar reemplazo','superset-settings':'Configuración de superserie','voice-edit':'Corregir captura','analysis-help':'Cómo leer este análisis','assistance':'Asistencia de sesión','framing-guide':'Preparar el encuadre','voice-audit':'Historial de correcciones'};
sheetTitle=id=>panelNames[id]||old.sheetTitle(id);
function panelField(label,key,value,attrs=''){return `<label class="input-label">${label}<input data-v2="${key}" value="${esc(value??'')}" ${attrs}></label>`;}
sheetContent=function(id){const r=row();switch(id){
 case 'view':return `<p class="sheet-subtitle">Vistas de registro</p>${[['cards','Tarjetas'],['list','Lista']].map(([id,t])=>btn('view',t+icon('right',15),'menu-row',`data-value="${id}"`)).join('')}`;
 case 'menu':return old.sheetContent(id)+menuRow('assistance','Ayuda y explicaciones','info');
 case 'v2-details':return `<p class="sheet-subtitle">${esc(ex().short)} · serie ${r.label}</p>${old.sheetContent('partials')}<label class="form-row"><span>Registrar ROM</span>${btn('toggle-rom','',`toggle ${state.showRom?'on':''}`,'aria-label="Mostrar ROM"')}</label>${state.showRom?`<label class="form-row">ROM ${fieldInput('rom',r.rom,'','Rango de movimiento')} %</label>`:''}${open('series-note','Nota de serie '+icon('right',14),'menu-row')}`;
 case 'series-note':return `<p class="sheet-subtitle">${esc(ex().short)} · serie ${r.label}</p><label class="input-label">Observación<textarea data-field="note" aria-label="Nota de la serie" placeholder="Escribe una observación…">${esc(r.note)}</textarea></label>`;
 case 'failure-detail':return `<p class="sheet-subtitle">Señala una incidencia de ejecución. Llegar al fallo muscular se informa en esfuerzo.</p><div class="choice-row">${['Molestia articular','Fallo técnico','Carga excesiva'].map(t=>btn('failure-cause',t,r.note===t?'selected':'',`data-value="${t}"`)).join('')}</div>${btn('mark-failed','Marcar error de ejecución','secondary full mt')}`;
 case 'tech-chain':return `<p class="sheet-subtitle">Principal ${r.weight} × ${r.value}. Selecciona un tramo para editarlo.</p>${r.segments.map((s,i)=>btn('v2-segment-open',`<span>${r.technique==='drop'?'Drop':'Tramo'} ${i+1}</span><strong>${s.weight} × ${s.reps}</strong>${icon('right',14)}`,'menu-row',`data-value="${i+1}"`)).join('')}${btn('v2-add-segment',icon('plus',15)+' Añadir tramo','secondary full mt',r.segments.length>=5?'disabled':'')}`;
 case 'movement-detail':return `<img class="v2-sheet-art" src="${EXERCISE_ART}" alt="Ilustración KPKN"><h3>${['Movilidad de tobillo','Apertura de cadera','Sentadilla sin carga'][state.movementIndex||0]}</h3><p class="sheet-subtitle">Explora el movimiento a tu ritmo antes de añadir carga.</p><div class="joint-strip">${['Tobillo','Rodilla','Cadera'].map(t=>btn('joint',t,'',`data-value="${t}"`)).join('')}</div>${btn('v2-movement-complete',state.mobility[state.movementIndex||0]?'Completado ✓':'Marcar completado','primary full mt')}`;
 case 'rest-suggestion':return `<div class="v2-rest-proposal"><div><small>PLANIFICADO</small><strong>${clock(rr().plan)}</strong></div><span>→</span><div><small>SUGERIDO</small><strong>${clock(rr().suggested)}</strong></div></div><p class="sheet-subtitle">Sugerencia de ejemplo para este descanso. El temporizador cambia sólo si la aplicas.</p><div class="v2-proposal-facts"><span>Última serie</span><strong>${rr().lastSet||'100 × 8 · RIR 2'}</strong><span>Tiempo transcurrido</span><strong>${clock(Math.max(0,rr().total-rr().seconds))}</strong><span>Restante tras aplicar</span><strong>${clock(Math.max(0,rr().suggested-(rr().total-rr().seconds)))}</strong></div><p class="v2-short-copy">La sugerencia de duración no es una medición de recuperación física.</p>${btn('v2-suggestion-apply','Aplicar '+clock(rr().suggested),'primary full')}${btn('close','Mantener descanso actual','text-action wide-text')}`;
 case 'feedback-discomforts':return `<p class="sheet-subtitle">${esc(state.exercises[state.feedbackExercise??state.ex].name)}</p><div class="choice-row">${['Sin molestias','Rodilla','Cadera','Espalda','Hombro'].map(t=>btn('v2-feedback-discomfort',t,state.feedbackDraft.discomforts.includes(t)?'selected':'',`data-value="${t}"`)).join('')}</div><div class="v2-history-note"><small>REPORTADA ANTES</small><strong>Molestia en rodilla</strong><p>Este dato proviene del historial de ejemplo, no de un diagnóstico.</p>${btn('v2-alert','Ver aviso','text-action','data-value="discomfort"')}</div>`;
 case 'tags':return `<div class="v2-context-header"><small>ETIQUETAS DE ESTE EJERCICIO</small><strong>${esc(ex().name)}</strong><p>Cada contexto conserva su referencia de carga.</p></div><div class="v2-tags">${ex().tagOptions.map(t=>{const c=ex().contexts[t];return `<div class="v2-tag-option ${ex().tags.includes(t)?'selected':''}">${btn('v2-tag-select',`<span class="v2-radio"></span><div><strong>${esc(t)}</strong><small>${esc(c?.previous||'Sin historial')}${ex().tags.includes(t)?' · Activa':''}</small></div>`,'',`data-value="${esc(t)}"`)}${btn('v2-tag-edit',icon('tune',16),'icon-btn',`data-value="${esc(t)}" aria-label="Editar etiqueta ${esc(t)}"`)}</div>`;}).join('')}</div>${btn('v2-tag-new',icon('plus',16)+' Nueva etiqueta','secondary full mt')}<p class="v2-short-copy">Cambiar el contexto afecta a los próximos registros. Las series ya guardadas mantienen su etiqueta.</p>`;
 case 'tag-change':return `<p class="sheet-subtitle">${esc(ex().name)}</p><div class="v2-context-change"><span>${esc(activeTag())}</span>${icon('right',20)}<strong>${esc(state.pendingTag)}</strong></div><div class="v2-history-note"><small>NUEVA REFERENCIA</small><strong>${esc(ex().contexts[state.pendingTag]?.previous||'Sin historial')}</strong><p>Se renovará el borrador de las series pendientes de este ejercicio. Los registros realizados se conservan.</p></div>${btn('v2-tag-apply','Cambiar contexto','primary full')}${open('tags','Mantener el actual','text-action wide-text')}`;
 case 'tag-setup':case 'tag-new':{const c=state.tagForm||{};return `<p class="sheet-subtitle">${esc(ex().name)}</p>${panelField('Nombre','tag-name',c.name)}<div class="two-fields mt">${panelField('Equipo / marca','tag-brand',c.brand)}${panelField('Carga base · kg','tag-base',c.base,'inputmode="decimal"')}</div><label class="input-label mt">Notas de setup<textarea data-v2="tag-notes">${esc(c.notes||'')}</textarea></label>${state.tagError?`<p class="v2-inline-error" role="alert">${esc(state.tagError)}</p>`:''}${id==='tag-setup'?`<div class="v2-history-note"><small>REFERENCIA DE ESTA ETIQUETA</small><strong>${esc(c.previous||'Sin historial')}</strong></div>${btn('v2-alert','Reiniciar referencia de historial','text-action danger','data-value="tag-reset"')}`:''}`;}
 case 'set-config':{const d=state.configDraft;return `<p class="sheet-subtitle">${esc(ex().short)} · serie ${r.label}<br>Los objetivos son independientes de lo registrado.</p><div class="segmented">${[['target','Objetivo'],['load','Carga'],['technique','Detalle']].map(([id,t])=>btn('v2-config-tab',t,state.configTab===id?'selected':'',`data-value="${id}"`)).join('')}</div><div class="v2-config-fields">${state.configTab==='target'?`<label class="input-label">Formato<select data-v2="config-format">${['Repeticiones','RM / TM','Solo RPE','Tiempo','Distancia','Unidad propia','AMRAP'].map(t=>`<option ${d.format===t?'selected':''}>${t}</option>`).join('')}</select></label><div class="two-fields">${panelField('Objetivo mínimo','config-min',d.min,'inputmode="decimal"')}${panelField('Objetivo máximo','config-max',d.max,'inputmode="decimal"')}</div><div class="two-fields"><label class="input-label">Intensidad<select data-v2="config-mode"><option ${d.mode==='RIR'?'selected':''}>RIR</option><option ${d.mode==='RPE'?'selected':''}>RPE</option></select></label>${panelField('Valor objetivo','config-effort',d.effort,'inputmode="decimal"')}</div>${panelField('Descanso después · segundos','config-rest',d.rest,'inputmode="numeric"')}`:state.configTab==='load'?`<div class="choice-row">${['Externa','Corporal','Lastre','Asistida'].map(t=>btn('v2-config-load',t,d.load===t?'selected':'',`data-value="${t}"`)).join('')}</div>${panelField('Referencia · kg','config-reference',d.reference??r.weight,'inputmode="decimal"')}<p class="v2-short-copy">La carga realmente utilizada se edita al registrar la serie.</p>`:`<label class="input-label">Propósito<select data-v2="config-purpose">${['Efectiva','AMRAP','Calibrador'].map(t=>`<option ${d.purpose===t?'selected':''}>${t}</option>`).join('')}</select></label>${open('v2-details','Parciales, ayuda y ROM '+icon('right',13),'menu-row')}${btn('v2-open-technique','Técnica avanzada '+icon('right',13),'menu-row')}<p class="v2-short-copy">El detalle de ejecución conserva su propio borrador.</p>`}</div><div class="section-label">Aplicar a</div><div class="choice-row">${[['one','Esta serie'],['pending','Pendientes del ejercicio']].map(([id,t])=>btn('v2-config-scope',t,state.configScope===id?'selected':'',`data-value="${id}"`)).join('')}</div>${state.configError?`<p class="v2-inline-error" role="alert">${state.configError}</p>`:''}`;}
 case 'series':return `<div class="v2-series-summary"><span>Serie ${r.label}</span><strong>${r.weight||'—'} × ${r.value}</strong><small>${effortLabel(r)}</small></div><div class="v2-options-grid">${btn('v2-config',icon('tune',20)+'<span>Configurar serie</span>')}${btn('face',icon('flame',20)+'<span>Avanzado</span>','','data-face="advanced"')}${open('v2-details',icon('plus',20)+'<span>Parciales y ROM</span>')}${open('series-note',icon('note',20)+'<span>Nota</span>')}</div>${btn('add-set',icon('plus',15)+' Añadir serie','menu-row')}${btn('omit',r.status==='skipped'?'Recuperar serie':'Omitir serie','menu-row')}${r.status!=='done'?open('delete-set','Quitar serie pendiente','menu-row danger'):''}`;
 case 'exercise':return `<div class="v2-context-header"><strong>${esc(ex().name)}</strong><p>${ex().sets.filter(s=>s.kind==='working').length} series · ${esc(activeTag())}</p></div><div class="v2-options-grid">${menuRow('tags','Etiquetas','tag')}${menuRow('history','Historial','history')}${menuRow('replace','Reemplazar','swap')}${btn('v2-config',icon('tune',20)+'<span>Series</span>')}${menuRow('exercise-info','Ficha','book')}${menuRow('reorder','Orden','route')}</div>`;
 case 'replace':return `<p class="sheet-subtitle">Reemplazar el trabajo pendiente de ${esc(ex().name)}.</p><label class="input-label">Buscar ejercicio<input data-v2="replace-search" value="${esc(state.replaceSearch||'')}" placeholder="Nombre del ejercicio" aria-label="Buscar reemplazo"></label><div class="v2-replacements">${['Sentadilla Frontal','Sentadilla Goblet','Prensa de Piernas'].filter(t=>t.toLowerCase().includes((state.replaceSearch||'').toLowerCase())).map((t,i)=>btn('v2-replace-select',`<span class="v2-replacement-icon">${icon(i===2?'grid':'swap',23)}</span><span><strong>${t}</strong><small>${i===2?'Máquina':i===1?'Mancuerna':'Barra'} · revisar antes de aplicar</small></span>${icon('right',15)}`,'menu-row',`data-value="${t}"`)).join('')}</div><div class="v2-history-note"><small>YA REALIZADO</small><strong>${ex().sets.filter(s=>s.kind==='working'&&s.status==='done').length} series se conservan</strong></div>`;
 case 'replace-preview':return `<div class="v2-replace-preview"><small>REEMPLAZO PARA LO PENDIENTE</small><h3>${esc(state.replaceChoice)}</h3><p>Desde ${esc(ex().name)}</p></div><div class="v2-inheritance"><div><strong>Se conserva del plan</strong><p>${ex().sets.filter(s=>s.kind==='working'&&s.status!=='done').length} series · objetivo 6–8 reps · RIR 2<br>Descanso · ${clock(Number(r.plan.rest)||120)}</p></div><div><strong>Contexto propio del reemplazo</strong><p>Carga e historial · etiquetas · setup · técnicas · lados y ROM</p></div></div><p class="v2-short-copy">La carga se elegirá con la referencia del nuevo ejercicio. Las series ya realizadas quedan asociadas al ejercicio original.</p>${btn('v2-replace-confirm','Aplicar reemplazo','primary full')}${open('replace','Elegir otro ejercicio','text-action wide-text')}`;
 case 'superset-settings':return `<p class="sheet-subtitle">Extensión de cuádriceps + curl femoral</p>${panelField('Rondas','super-rounds',state.superRounds||3,'inputmode="numeric"')}${panelField('Entre ejercicios · s','super-between',state.superBetween||20,'inputmode="numeric"')}${panelField('Al terminar ronda · s','super-after',state.superAfter||120,'inputmode="numeric"')}<p class="v2-short-copy">La navegación alterna A1 y A2 dentro de cada ronda.</p>`;
 case 'voice':return voicePicker();
 case 'voice-edit':{const e=state.voiceEditDraft;return e?`<div class="v2-transcript-original"><small>SE ESCUCHÓ</small><p>«${esc(e.said)}»</p></div><div class="two-fields">${panelField('Carga · kg','voice-weight',e.weight,'inputmode="decimal"')}${panelField('Repeticiones','voice-reps',e.reps,'inputmode="numeric"')}</div>${panelField('RIR realizado','voice-effort',e.effort,'inputmode="decimal"')}<p class="v2-short-copy">Corregir actualiza esta captura. No crea otra serie.</p>${state.voiceError?`<p class="v2-inline-error">${esc(state.voiceError)}</p>`:''}`:'';}
 case 'framing-guide':return `<p class="sheet-subtitle">Sentadilla · perfil lateral de este ejemplo.</p><div class="v2-history-note"><strong>01 · Coloca la cámara a un lado</strong><p>Apóyala en una superficie estable y mantén el móvil nivelado. La vista se adapta al ejercicio que vas a analizar.</p></div><div class="v2-history-note"><strong>02 · Deja espacio al movimiento</strong><p>Incluye cabeza, pies y barra durante todo el recorrido. Deja margen arriba y abajo, también en la posición más baja.</p></div><div class="v2-history-note"><strong>03 · Comprueba lo que se ve</strong><p>Una sola persona, articulaciones visibles y luz suficiente. Si el perfil requiere un disco para calibrar, también debe quedar visible.</p></div><div class="v2-history-note"><strong>04 · Espera la confirmación</strong><p>La guía da una indicación cada vez. «Encuadre listo» confirma la captura, no la calidad técnica del ejercicio.</p></div>`;
 case 'analysis-help':return `<p class="sheet-subtitle">Ejemplo interactivo con datos sintéticos y figura ilustrada. No es un análisis de una grabación real.</p><div class="v2-history-note"><strong>Qué se puede comprobar</strong><p>Seleccionar una repetición, desplazar la línea de tiempo, activar capas y consultar las métricas disponibles.</p></div><div class="v2-history-note"><strong>Unidades y confianza</strong><p>Sin escala física validada, la velocidad permanece en unidades relativas. Un dato ausente se muestra como «—»; los valores estimados llevan «≈».</p></div>`;
 case 'assistance':return `<p class="sheet-subtitle">Propuesta: ayuda sólo cuando aporta una explicación o una acción concreta.</p>${menuRow('history','Por qué aparece esta referencia','history')}${menuRow('rest-suggestion','Revisar descanso sugerido','timer')}${menuRow('analysis-help','Entender las métricas del vídeo','info')}<div class="v2-history-note"><strong>Relator permanente</strong><p>Su retirada se propone para esta revisión. Sus funciones útiles se conservan en el lugar donde se necesita cada explicación.</p></div>`;
 default:return old.sheetContent(id);
 }};
sheetFooter=function(id){if(['rest-suggestion','replace-preview','movement-detail','voice'].includes(id))return '';if(['tag-setup','tag-new'].includes(id))return `<div class="sheet-footer">${btn('v2-tag-save','Guardar etiqueta','primary full')}</div>`;if(id==='set-config')return `<div class="sheet-footer">${btn('v2-config-save','Guardar objetivos','primary full')}${btn('v2-config-cancel','Cancelar','text-action wide-text')}</div>`;if(id==='superset-settings')return '<div class="sheet-footer">'+btn('v2-super-save','Guardar superserie','primary full')+'</div>';if(id==='voice-edit')return `<div class="sheet-footer">${btn('v2-voice-save',state.voiceEvents.find(e=>e.id===state.voiceEdit)?.status==='review'?'Confirmar y registrar':'Guardar corrección','primary full')}</div>`;return old.sheetFooter(id);};
sheet=function(){let html=old.sheet();if(state.sheet==='voice')html=html.replace('class="sheet ','class="sheet v2-voice-picker ').replace('class="sheet"','class="sheet v2-voice-picker"');return html;};
function alertOverlay(){if(!state.alert)return '';const kinds={discomfort:['Molestia reportada antes','En el historial de este ejercicio hay una molestia de rodilla. Revisa cómo te encuentras hoy.','Entendido','Ver opciones del ejercicio'],save:['No se pudo guardar','Tu borrador sigue disponible. Reintenta cuando quieras.','Reintentar','Volver al registro'],conflict:['Ya hay una sesión en curso','Puedes reanudar Pierna · Semana 1. Empezar otra descartaría la sesión pendiente.','Reanudar sesión','Revisar descarte'],discard:['¿Descartar la sesión pendiente?','Se perderían los datos de esa sesión que todavía no hayas guardado.','Conservar sesión','Descartar en la demo'],'tag-reset':['¿Reiniciar esta referencia?','La referencia de la etiqueta se calcularía desde este momento. Los registros originales se conservan.','Conservar referencia','Reiniciar en la demo'],'config-dirty':['Tienes cambios sin guardar','Puedes volver a la configuración o descartar esta edición.','Seguir editando','Descartar cambios']};const a=kinds[state.alert]||kinds.save;return `<div class="v2-alert-backdrop"><section class="v2-alert" role="alertdialog" aria-modal="true" aria-label="${a[0]}"><div class="v2-alert-icon">${icon(state.alert==='save'?'undo':'info',24)}</div><h2>${a[0]}</h2><p>${a[1]}</p>${btn('v2-alert-primary',a[2],'primary full')}${btn('v2-alert-secondary',a[3],'text-action wide-text')}</section></div>`;}
function surfaceTop(label,title){return `<div class="v2-full-top"><div><small>${label}</small><strong>${title}</strong></div>${btn('v2-surface-close',icon('close',18),'icon-btn','aria-label="Cerrar vista"')}</div>`;}
function motionDiagram(){const progress=(state.analysisFrame%10)/10,depth=(Math.sin(progress*Math.PI*2)+1)/2;const hipY=88+depth*47,hipX=153-depth*19,shoulderY=hipY-51,shoulderX=hipX+9+depth*10,barY=shoulderY+8;return `<svg viewBox="0 0 320 200" class="v2-pose-diagram" aria-label="Ejemplo ilustrado de trayectoria; fotograma ${state.analysisFrame}"><defs><linearGradient id="poseGround" x1="0" x2="1"><stop stop-color="#0f141a"/><stop offset="1" stop-color="#161b21"/></linearGradient></defs><rect width="320" height="200" fill="url(#poseGround)"/><path d="M0 171H320M80 0V200M160 0V200M240 0V200" stroke="#ffffff08"/><ellipse cx="153" cy="174" rx="61" ry="8" fill="#000" opacity=".5"/>${state.analysisLayers.includes('bar')?'<path d="M169 43 C173 65 161 92 161 122 C165 97 171 69 169 43" fill="none" stroke="#8fb2ff" stroke-width="2" stroke-dasharray="4 3"/>':''}${state.analysisLayers.includes('body')?'<path d="M153 86 Q137 110 135 136" fill="none" stroke="#f49a6e" stroke-width="1.5" stroke-dasharray="3 3"/>':''}<path d="M${shoulderX} ${shoulderY} L${hipX} ${hipY} L185 137 L165 169 M${hipX} ${hipY} L124 138 L139 169" stroke="#d8d5ce" fill="none" stroke-width="9" stroke-linecap="round" stroke-linejoin="round"/><circle cx="${shoulderX+1}" cy="${shoulderY-17}" r="10" fill="#d8d5ce"/><path d="M${shoulderX} ${shoulderY+5}L${shoulderX+22} ${shoulderY+22}L${shoulderX+31} ${barY}" fill="none" stroke="#d8d5ce" stroke-width="6" stroke-linecap="round"/><path d="M109 ${barY} H218" stroke="#f2eee6" stroke-width="4"/><path d="M112 ${barY-13}V${barY+13}M118 ${barY-17}V${barY+17}M208 ${barY-17}V${barY+17}M214 ${barY-13}V${barY+13}" stroke="#b0aba2" stroke-width="5"/>${state.analysisLayers.includes('body')?[[shoulderX,shoulderY],[hipX,hipY],[185,137],[165,169]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="4" fill="#f49a6e" stroke="#161616" stroke-width="2"/>`).join(''):''}<text x="16" y="22" fill="#8e8980" font-size="9" font-family="Inter">VISTA LATERAL · DEMOSTRACIÓN</text><text x="16" y="188" fill="#c4bfb6" font-size="9" font-family="Inter">${depth>.6?'Descenso / fondo':'Ascenso'} · repetición ${state.analysisRep}</text></svg>`;}
function analysisSurface(){const tab=state.analysisTab;return `<section class="v2-fullscreen v2-analysis-surface" aria-label="Análisis detallado de vídeo">${statusbar()}${surfaceTop('ANÁLISIS · DEMO',ex().short+' · serie '+row().label)}<div class="v2-analysis-media"><div class="v2-pose-host">${motionDiagram()}</div><div class="v2-video-controls">${btn('v2-analysis-play',icon(state.analysisPlaying?'pause':'play',17),'',`aria-label="${state.analysisPlaying?'Pausar':'Reproducir'} análisis"`)}<input type="range" min="0" max="100" value="${state.analysisFrame}" data-v2="analysis-frame" aria-label="Fotograma del vídeo"><span data-analysis-time>${(state.analysisFrame*.24).toFixed(1)} s</span>${open('analysis-help',icon('info',16),'','aria-label="Acerca del análisis"')}</div></div><div class="v2-analysis-tabs">${[['replay','Trayectoria'],['metrics','Métricas'],['reps','Repeticiones']].map(([id,t])=>btn('v2-analysis-tab',t,tab===id?'selected':'',`data-value="${id}"`)).join('')}</div><div class="v2-analysis-content">${tab==='replay'?`<div class="v2-analysis-layers">${[['bar','Trayectoria de barra'],['body','Articulaciones']].map(([id,t])=>btn('v2-analysis-layer',`<i class="${id}"></i>${t}`,state.analysisLayers.includes(id)?'selected':'',`data-value="${id}" aria-pressed="${state.analysisLayers.includes(id)}"`)).join('')}</div><div class="v2-analysis-insight"><div><small>REPETICIÓN ${state.analysisRep}</small><h3>${state.analysisPartial.includes(state.analysisRep)?'Parcial':'Completa'}</h3></div><div><small>ROM ESTIMADO</small><strong>≈${state.analysisPartial.includes(state.analysisRep)?'58':'92'}<span>°</span></strong></div></div><p class="v2-analysis-caption">Selecciona una repetición y recorre su movimiento. Las líneas muestran posiciones del ejemplo.</p>${repStrip()}`:tab==='metrics'?`<div class="v2-analysis-metrics">${[['Repeticiones',state.analysisCount||'8 + 2','completas + parciales'],['Tiempo bajo tensión','24 s','serie de ejemplo'],['Tempo','2 · 0 · 1','mediana · s'],['ROM','≈92°','estimado · vista lateral'],['Pérdida de velocidad','≈16%','comparación relativa'],['Velocidad media','—','sin escala física validada']].map(([t,v,h])=>`<div><span>${t}</span><strong>${v}</strong><small>${h}</small></div>`).join('')}</div>`:`<div class="v2-rep-metric-select">${['Velocidad','ROM','Tiempo'].map(t=>btn('v2-analysis-metric',t,state.analysisMetric===t?'selected':'',`data-value="${t}"`)).join('')}</div><div class="v2-rep-chart">${[94,91,93,88,90,85,83,79,57,52].map((v,i)=>btn('v2-analysis-rep',`<i style="height:${state.analysisMetric==='Tiempo'?65+i*2:v}%"></i><span>${i+1}</span>`,state.analysisRep===i+1?'selected':'',`data-value="${i+1}" aria-label="Ver repetición ${i+1}"`)).join('')}</div><div class="v2-rep-detail"><strong>Repetición ${state.analysisRep}</strong><span>${state.analysisPartial.includes(state.analysisRep)?'Parcial · ≈58°':'Completa · ≈92°'}</span>${btn('v2-rep-toggle',state.analysisPartial.includes(state.analysisRep)?'Marcar completa':'Marcar parcial','text-action')}</div><p class="v2-analysis-caption">${state.analysisMetric==='Velocidad'?'Velocidad relativa; no se muestran m/s sin calibración.':'Selecciona una barra para revisar esa repetición.'}</p>`}</div><div class="v2-full-bottom"><div class="v2-analysis-result-label"><span>Conteo propuesto · demo</span><strong>${state.analysisCount||'8 + 2'} reps</strong></div>${btn('v2-analysis-use','Revisar y usar resultado','primary full')}</div></section>`;}
function repStrip(){return `<div class="v2-rep-strip">${Array.from({length:10},(_,i)=>btn('v2-analysis-rep',i+1,state.analysisRep===i+1?'selected':'',`data-value="${i+1}" aria-label="Ver repetición ${i+1}"`)).join('')}</div>`;}
function updateAnalysis(){if(state.fullSurface!=='analysis')return;$$('.v2-pose-host').forEach(e=>e.innerHTML=motionDiagram());$$('[data-analysis-time]').forEach(e=>e.textContent=(state.analysisFrame*.24).toFixed(1)+' s');$$('[data-action="v2-analysis-rep"]').forEach(e=>e.classList.toggle('selected',Number(e.dataset.value)===state.analysisRep));$$('.v2-analysis-insight>div:first-child>small').forEach(e=>e.textContent='REPETICIÓN '+state.analysisRep);$$('.v2-analysis-insight h3').forEach(e=>e.textContent=state.analysisPartial.includes(state.analysisRep)?'Parcial':'Completa');$$('.v2-analysis-insight strong').forEach(e=>e.innerHTML='≈'+(state.analysisPartial.includes(state.analysisRep)?'58':'92')+'<span>°</span>');}
function waveform(){return `<div class="v2-waveform ${state.voicePaused?'paused':''}">${Array.from({length:25},(_,i)=>`<i style="--h:${12+Math.sin(i*1.7)**2*30}px;--delay:${i*.06}s"></i>`).join('')}</div>`;}
function voicePicker(){const step=state.voiceStep;return `<p class="sheet-subtitle">Elige cómo entrenar con voz.</p>${step==='choices'?`<div class="v2-voice-choices">${[['Con música','Música','Tu audio, con captura de voz.','play'],['Manos libres','Manos libres','Escucha continua de tus comandos.','mic']].map(([id,t,h,i])=>btn('voice-mode',`${icon(i,22)}<div><strong>${t}</strong><small>${h}</small></div><span class="v2-radio"></span>`,state.voiceMode===id?'selected':'',`data-value="${id}"`)).join('')}</div><div class="v2-voice-route"><span>Entrada de audio</span><strong>Micrófono · ejemplo</strong></div>${btn('v2-voice-test','Probar este modo','primary full')}`:`<div class="v2-voice-check">${waveform()}<h3>${step==='passed'?'Te escuchamos.':'Di «Listo»'}</h3><p>${step==='passed'?'Prueba de demostración completada.':'Comprueba el modo antes de entrenar.'}</p>${step==='passed'?btn('v2-voice-activate','Activar modo de voz','primary full'):btn('v2-voice-pass','Simular «Listo»','primary full')}</div>`}${btn('close','Ahora no','text-action wide-text')}`;}
function voiceSurface(){const filtered=state.voiceEvents.filter(e=>state.voiceFilter==='all'||e.status==='review');return `<section class="v2-fullscreen v2-voice-surface" aria-label="Conversación y registros de voz">${statusbar()}${surfaceTop('MODO VOZ · DEMOSTRACIÓN',state.voiceMode)}<div class="v2-voice-listening">${waveform()}<div><strong>${state.voicePaused?'En pausa':'Te escucho'}</strong><span>${esc(ex().short)} · serie ${row().label}</span></div>${btn('v2-voice-pause',icon(state.voicePaused?'mic':'pause',18),'icon-btn',`aria-label="${state.voicePaused?'Reanudar':'Pausar'} voz"`)}</div><div class="v2-voice-tabs">${btn('v2-voice-filter','Conversación',state.voiceFilter==='all'?'selected':'','data-value="all"')}${btn('v2-voice-filter','Por revisar · '+state.voiceEvents.filter(e=>e.status==='review').length,state.voiceFilter==='review'?'selected':'','data-value="review"')}</div><div class="v2-voice-timeline" data-scroll="voice"><div class="v2-voice-day">HOY · PIERNA, SEMANA 1</div>${filtered.map(e=>`<article class="v2-voice-event"><div class="v2-voice-said"><small>TÚ · ${e.time}</small><p>«${esc(e.said)}»</p></div><div class="v2-voice-record ${e.status==='review'?'review':''}"><div class="v2-voice-record-top"><span>${e.status==='review'?'Revisar antes de registrar':e.version>1?'Corregida · v'+e.version:'Serie registrada'}</span>${icon(e.status==='review'?'info':'check',14)}</div><div class="v2-voice-record-values"><strong>${esc(e.weight)}<small> kg</small></strong><span>×</span><strong>${esc(e.reps)}<small> reps</small></strong><span>${e.effort?'RIR '+e.effort:'Falta RIR'}</span></div><div class="v2-voice-record-actions"><span>${esc(state.exercises[e.exercise]?.short||'Ejercicio')} · ${e.set}</span>${btn('v2-voice-edit','Editar '+icon('tune',13),'',`data-id="${e.id}"`)}</div>${e.status==='review'?btn('v2-voice-confirm','Revisar captura','secondary full','data-id="'+e.id+'"'):''}${e.previous?`<small class="v2-voice-audit">Antes: ${esc(e.previous)} · ${btn('v2-voice-history','Ver cambios','',`data-id="${e.id}"`)}</small>`:''}</div></article>`).join('')}${filtered.length===0?'<p class="v2-voice-empty">Todas las capturas están revisadas.</p>':''}</div><div class="v2-voice-compose">${btn('v2-voice-example',icon('mic',18)+' Escuchar frase de ejemplo','secondary full',state.voicePaused?'disabled':'')}<small>Puedes revisar y corregir cada captura.</small>${btn('v2-voice-off','Desactivar modo voz','text-action wide-text')}</div></section>`;}
const framingMessages={ok:'Encuadre correcto. Puedes comenzar.',feet:'Los pies quedan fuera. Aleja un poco la cámara.',person:'No se detecta al atleta. Entra en el encuadre.',angle:'Coloca la cámara de lado para esta sentadilla.',multiple:'Debe aparecer una sola persona en el encuadre.'};
function framingFigure(){return `<svg class="v2-framing-figure" viewBox="0 0 320 360" aria-label="Figura lateral de demostración, con margen alrededor del cuerpo y la barra"><defs><linearGradient id="framing-bg" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#18212b"/><stop offset="1" stop-color="#0a1017"/></linearGradient></defs><rect width="320" height="360" fill="url(#framing-bg)"/><path d="M0 90H320M0 180H320M0 270H320M80 0V360M160 0V360M240 0V360" stroke="#ffffff07"/><path d="M45 318H275" stroke="#ffffff24"/><ellipse cx="165" cy="320" rx="60" ry="7" fill="#0007"/><path d="M147 145L139 222L183 264L167 313M139 222L120 264L137 312" fill="none" stroke="#aba9a3" stroke-width="15" stroke-linecap="round" stroke-linejoin="round"/><path d="M142 149L145 180L139 222" stroke="#d5d2ca" stroke-width="28" stroke-linecap="round"/><path d="M146 147L175 181L186 143" stroke="#c9b5a4" stroke-width="9" fill="none" stroke-linecap="round"/><path d="M149 135L150 120" stroke="#c9b5a4" stroke-width="9"/><ellipse cx="151" cy="108" rx="13" ry="18" fill="#c9b5a4"/><path d="M157 102L169 109L159 113" fill="#c9b5a4"/><path d="M139 107Q136 86 153 87Q164 89 163 100" fill="#34383b"/><path d="M132 313H149M162 314H182" stroke="#eeeae2" stroke-width="8" stroke-linecap="round"/><path d="M91 143H231" stroke="#d7d8d6" stroke-width="4"/><path d="M97 128V158M104 123V163M218 123V163M225 128V158" stroke="#777f86" stroke-width="6"/><circle cx="161" cy="106" r="2" fill="#272727"/><text x="18" y="344" fill="#a1acb8" font-size="8" font-family="Inter">PERFIL LATERAL · FIGURA DE DEMOSTRACIÓN</text></svg>`;}
function captureSurface(){const f=state.framing||'ok';return `<section class="v2-fullscreen v2-capture-surface" aria-label="Captura con guía de encuadre">${statusbar()}${surfaceTop('MODO VISUAL · DEMO',ex().short)}<div class="v2-framing-preview ${f==='feet'?'framing-feet':''}">${framingFigure()}<div class="v2-framing-corners ${f==='ok'?'ready':''}"><i></i><i></i><i></i><i></i></div><div class="v2-framing-status">${icon(f==='ok'?'check':'info',16)}<span>${f==='ok'?'Cuerpo y barra visibles':framingMessages[f]}</span></div>${open('framing-guide','Vista lateral · cómo encuadrar','v2-framing-view')}<div class="v2-framing-recording">${state.recording?'<i></i> GRABANDO':'PREPARAR CAPTURA'}</div></div><div class="v2-framing-guide"><div><strong>Guía hablada de encuadre</strong><small>Funciona aunque Modo Voz esté apagado.</small></div>${btn('v2-guide-toggle','',`toggle ${state.spokenGuide?'on':''}`,`aria-label="Guía hablada independiente" aria-pressed="${!!state.spokenGuide}"`)}</div><div class="v2-spoken-caption">${icon('info',16)}<span>${framingMessages[f]}</span>${btn('v2-guide-speak',icon('play',15),'','aria-label="Escuchar guía de ejemplo"')}</div><div class="v2-capture-voice"><span>Comandos de voz</span>${btn('v2-capture-voice',state.voice?(state.voicePaused?'Reanudar comandos':'Desactivar comandos'):'Activar Modo Voz','text-action')}<small>${state.voice?'«Iniciar vídeo» · «Detener vídeo»':'Activa Modo Voz para controlar la grabación.'}</small></div><div class="v2-capture-actions">${btn('v2-capture-start',state.recording?icon('pause',21):icon('camera',23),'v2-record-control',`aria-label="${state.recording?'Detener':'Iniciar'} grabación de ejemplo"`)}<div><strong>${state.recording?'Grabación en curso':f==='ok'?'Listo para grabar':'Ajusta el encuadre'}</strong><small>${state.recording?'Toca para detener':'El encuadre se revisa antes de comenzar'}</small></div>${state.recording?btn('v2-command-stop','«Detener vídeo»','secondary',state.voice&&!state.voicePaused?'':'disabled'):btn('v2-command-start','«Iniciar vídeo»','secondary',state.voice&&!state.voicePaused?'':'disabled')}</div><div class="v2-demo-framing"><span>PROBAR ENCUADRE</span>${[['ok','Correcto'],['feet','Pies fuera'],['angle','Ángulo']].map(([id,t])=>btn('v2-framing',t,f===id?'selected':'',`data-value="${id}"`)).join('')}</div></section>`;}
commitRecord=function(partial=false){const current=row(),ei=state.ex,wasDone=current.status==='done',last=ex().sets.filter(s=>s.kind==='working'&&s.status!=='done').length===1,summary=current.weight+' × '+current.value+' · '+effortLabel(current);current.recordTag=activeTag();old.commit(partial);if(!wasDone&&!state.result){state.phase='rest';rr().presentation='full';if(state.scene==='superset'){const duration=ei===0?(state.superBetween??20):(state.superAfter??120);rr().total=duration;rr().seconds=duration;rr().plan=duration;rr().suggested=duration;}rr().lastSet=summary;state.restPanel=last?'feedback':'clock';state.feedbackExercise=ei;}};
onAction=function(action,d,el){const r=row();switch(action){
 case 'v2-super-save':{const d=state.superDraft||{},rounds=Number(d.rounds??state.superRounds??3),between=Number(d.between??state.superBetween??20),after=Number(d.after??state.superAfter??120);if(!Number.isInteger(rounds)||rounds<1||rounds>6||between<0||after<0||!Number.isFinite(between+after)){notify('Revisa rondas (1–6) y tiempos.');break;}const completed=Math.max(...state.exercises.map(e=>e.sets.filter(s=>s.status==='done').length));if(rounds<completed){notify('Las rondas registradas se conservan.');break;}state.superRounds=rounds;state.superBetween=between;state.superAfter=after;state.exercises.forEach((e,ei)=>{while(e.sets.length<rounds)e.sets.push(makeSet('super-'+ei+'-'+e.sets.length,String(e.sets.length+1),ei?'40':'45','12'));e.sets=e.sets.slice(0,rounds);});if(!ex().sets.some(s=>s.id===state.selected)){state.selected=ex().sets.at(-1).id;state.openRow=state.selected;}state.superDraft=null;state.sheet=null;break;}
 case 'v2-config':startConfig();state.sheet='set-config';break;
 case 'v2-config-tab':state.configTab=d.value;break;
 case 'v2-config-scope':state.configScope=d.value;break;
 case 'v2-config-load':state.configDraft.load=d.value;state.configDirty=true;break;
 case 'v2-config-save':{const p=state.configDraft;state.configError='';if([p.min,p.max,p.rest,p.effort].some(v=>String(v).trim()===''||!Number.isFinite(num(v))||num(v)<0)||num(p.max)<num(p.min)||(p.mode==='RPE'&&num(p.effort)>10)){state.configError='Revisa objetivos, intensidad y descanso.';break;}pushUndo();const targets=state.configScope==='one'?[r]:ex().sets.filter(s=>s.kind==='working'&&s.status!=='done');targets.forEach(s=>s.plan=structuredClone(p));state.configDirty=false;state.sheet=null;notify('Objetivos actualizados. El registro realizado se conserva.');break;}
 case 'v2-config-cancel':if(state.configDirty)state.alert='config-dirty';else state.sheet=null;break;
 case 'close':if(state.sheet==='set-config'&&state.configDirty){state.alert='config-dirty';break;}return old.action(action,d,el);
 case 'v2-open-technique':state.sheet=null;state.face='advanced';break;
 case 'v2-segment-prev':state.techSegment=Math.max(0,state.techSegment-1);break;
 case 'v2-segment-next':state.techSegment=Math.min(r.segments.length,state.techSegment+1);break;
 case 'v2-segment-open':state.techSegment=Number(d.value);state.sheet=null;state.face='advanced';break;
 case 'v2-add-segment':old.action('add-segment',d,el);state.sheet=null;state.face='advanced';break;
 case 'v2-warm-page':warmPage=Math.max(0,Math.min(Math.ceil(ex().sets.filter(s=>s.kind==='warmup').length/3)-1,warmPage+Number(d.direction)));break;
 case 'v2-movement':state.movementIndex=Number(d.index);state.sheet='movement-detail';break;
 case 'v2-movement-complete':state.mobility[state.movementIndex||0]=true;state.sheet=null;break;
 case 'mobility-view':if(view==='list'&&d.value==='global'){state.joint='Tobillo';state.sheet='joint';break;}return old.action(action,d,el);
 case 'rest-minimize':case 'v2-rest-card':rr().presentation='card';state.phase='rest';break;
 case 'rest-show':case 'v2-rest-full':rr().presentation='full';state.phase='rest';break;
 case 'v2-rest-end':case 'rest-end':if(state.restPanel==='feedback'&&!state.feedbackDraft.saved){rr().running=false;rr().seconds=0;notify('Descanso terminado. El feedback sigue pendiente.');break;}rr().active=false;rr().running=false;rr().presentation='card';state.phase=state.scene==='warmup-rest'?'warmup':'sets';state.restPanel='clock';window.KpknArcade?.stop();break;
 case 'record':if(state.phase==='rest')return onAction('v2-rest-end',d,el);return old.action(action,d,el);
 case 'rest-adjust':{const delta=Number(d.amount),elapsed=Math.max(0,rr().total-rr().seconds);rr().seconds=Math.max(0,rr().seconds)+delta;rr().total=Math.max(1,elapsed+Math.max(0,rr().seconds));if(rr().seconds>0)rr().running=true;break;}
 case 'v2-suggestion-apply':{const elapsed=rr().total-rr().seconds;rr().total=rr().suggested;rr().seconds=Math.max(0,rr().suggested-elapsed);state.suggestionApplied=true;state.sheet=null;break;}
 case 'v2-rest-panel':state.restPanel=d.value;window.KpknArcade?.stop();break;
 case 'v2-feedback-discomfort':{const choices=state.feedbackDraft.discomforts;state.feedbackDraft.discomforts=d.value==='Sin molestias'?['Sin molestias']:choices.includes(d.value)?choices.filter(x=>x!==d.value):[...choices.filter(x=>x!=='Sin molestias'),d.value];break;}
 case 'v2-previous':state.feedbackDraft.previous=d.value;break;
 case 'v2-feedback-save':state.feedbackDraft.saved=true;state.restPanel='clock';notify('Feedback del ejercicio guardado en la demo.');if(!rr().running){state.phase='sets';rr().presentation='card';}break;
 case 'v2-feedback-skip':state.restPanel='clock';if(!rr().running){state.phase='sets';rr().presentation='card';}break;
 case 'v2-game':state.arcadeMode=d.value;state.restPanel='game';window.KpknArcade?.start(d.value);break;
 case 'v2-game-start':window.KpknArcade?.play();return false;
 case 'v2-game-restart':window.KpknArcade?.start(state.arcadeMode);window.KpknArcade?.play();return false;
 case 'v2-game-input':window.KpknArcade?.input();return false;
 case 'v2-list-controls':listControls=d.value;break;
 case 'v2-row-record':{selectRow(d.id,d.ex,false);if(row().status==='done'){state.sheet='series';break;}if(row().effort===null){state.error='Marca el esfuerzo para registrar esta serie.';break;}register();break;}
 case 'v2-tag-select':if(d.value!==activeTag()){state.pendingTag=d.value;state.sheet='tag-change';}break;
 case 'v2-tag-apply':{pushUndo();ex().tags=[state.pendingTag];ex().previous=ex().contexts[state.pendingTag]?.previous||'Sin historial';ex().sets.filter(s=>s.kind==='working'&&s.status!=='done').forEach(s=>{s.weight=ex().contexts[state.pendingTag]?.weight||'';s.effort=null;s.partials=0;s.assisted=0;s.note='';});state.sheet=null;notify('Contexto cambiado para las próximas series.');break;}
 case 'v2-tag-edit':state.tagOriginal=d.value;state.tagForm={...ex().contexts[d.value]};state.tagError='';state.sheet='tag-setup';break;
 case 'v2-tag-new':state.tagOriginal=null;state.tagForm={name:'',brand:'',base:'',notes:'',previous:'Sin historial',weight:''};state.tagError='';state.sheet='tag-new';break;
 case 'v2-tag-save':{const name=state.tagForm.name.trim(),collision=ex().tagOptions.find(t=>t.toLocaleLowerCase()===name.toLocaleLowerCase()&&t!==state.tagOriginal);if(!name||collision||state.tagForm.base&&(!Number.isFinite(num(state.tagForm.base))||num(state.tagForm.base)<0)){state.tagError=collision?'Ya existe una etiqueta con ese nombre.':'Revisa el nombre y la carga base.';break;}pushUndo();if(state.tagOriginal){ex().tagOptions=ex().tagOptions.map(t=>t===state.tagOriginal?name:t);ex().tags=ex().tags.map(t=>t===state.tagOriginal?name:t);delete ex().contexts[state.tagOriginal];}else ex().tagOptions.push(name);ex().contexts[name]={...state.tagForm,name};state.sheet='tags';state.tagError='';break;}
 case 'v2-replace-select':state.replaceChoice=d.value;state.sheet='replace-preview';break;
 case 'v2-replace-confirm':{pushUndo();const pending=ex().sets.filter(s=>s.kind==='working'&&s.status!=='done');if(!pending.length){notify('No hay series pendientes.');break;}const id='replacement-'+Date.now(),replacement={id,name:state.replaceChoice,short:state.replaceChoice,equipment:state.replaceChoice.includes('Prensa')?'Máquina':'Barra',previous:'Sin historial del reemplazo',tags:[],tagOptions:['Competición','Tempo','Sin cinturón'],sets:pending.map((s,i)=>({...makeSet(id+'-'+i,String(i+1),'',s.value),plan:structuredClone(s.plan)}))};ex().sets=ex().sets.filter(s=>!pending.includes(s));state.exercises.splice(state.ex+1,0,replacement);state.ex++;state.selected=replacement.sets[0].id;state.openRow=state.selected;state.sheet=null;enrich();notify('Reemplazo aplicado. Elige la carga del nuevo ejercicio.');break;}
 case 'replace':state.replaceChoice=d.value;state.sheet='replace-preview';break;
 case 'v2-alert':state.alert=d.value;break;
 case 'v2-alert-primary':state.alert=null;break;
 case 'v2-alert-secondary':if(state.alert==='discomfort'){state.alert=null;state.sheet='exercise';}else if(state.alert==='conflict'){state.alert='discard';}else if(state.alert==='config-dirty'){state.configDirty=false;state.alert=null;state.sheet=null;}else if(state.alert==='tag-reset'){ex().contexts[state.tagForm?.name||activeTag()].previous='Sin referencia desde el reinicio';state.alert=null;notify('Referencia reiniciada sólo en la demostración.');}else {state.alert=null;notify('Acción simulada. No se modificaron datos reales.');}break;
 case 'v2-analysis':state.fullSurface='analysis';state.sheet=null;state.analysisPlaying=false;break;
 case 'analysis-use':state.fullSurface='analysis';state.sheet=null;break;
 case 'v2-analysis-tab':state.analysisTab=d.value;break;
 case 'v2-analysis-layer':state.analysisLayers=state.analysisLayers.includes(d.value)?state.analysisLayers.filter(x=>x!==d.value):[...state.analysisLayers,d.value];break;
 case 'v2-analysis-rep':state.analysisRep=Number(d.value);state.analysisFrame=(Number(d.value)-1)*10+5;state.analysisPlaying=false;break;
 case 'v2-analysis-metric':state.analysisMetric=d.value;break;
 case 'v2-analysis-play':state.analysisPlaying=!state.analysisPlaying;break;
 case 'v2-rep-toggle':state.analysisPartial=state.analysisPartial.includes(state.analysisRep)?state.analysisPartial.filter(i=>i!==state.analysisRep):[...state.analysisPartial,state.analysisRep];state.analysisCount=(10-state.analysisPartial.length)+' + '+state.analysisPartial.length;notify('Clasificación de esta repetición corregida.');break;
 case 'v2-analysis-use':state.fullSurface=null;state.analysisPlaying=false;r.value=String(10-state.analysisPartial.length);r.partials=state.analysisPartial.length;state.face='front';notify('Resultado incorporado al borrador. Aún no registra la serie.');break;
 case 'v2-surface-close':state.fullSurface=null;state.analysisPlaying=false;state.recording=false;break;
 case 'v2-voice':case 'voice':if(state.voice)state.fullSurface='voice';else {state.sheet='voice';state.voiceStep='choices';}break;
 case 'v2-voice-test':state.voiceStep='listening';break;
 case 'v2-voice-pass':state.voiceStep='passed';state.voiceVerified=true;break;
 case 'v2-voice-activate':if(state.voiceVerified){state.voice=true;state.voicePaused=false;state.sheet=null;state.fullSurface=state.voiceReturn==='capture'?'capture':'voice';state.voiceReturn=null;}break;
 case 'v2-voice-off':state.voice=false;state.voicePaused=false;state.fullSurface=null;break;
 case 'v2-voice-pause':state.voicePaused=!state.voicePaused;break;
 case 'v2-voice-filter':state.voiceFilter=d.value;break;
 case 'v2-voice-edit':case 'v2-voice-confirm':state.voiceEdit=Number(d.id);state.voiceEditDraft=structuredClone(state.voiceEvents.find(e=>e.id===state.voiceEdit));state.voiceError='';state.sheet='voice-edit';break;
 case 'v2-voice-save':{const e=state.voiceEvents.find(e=>e.id===state.voiceEdit),d=state.voiceEditDraft;if(!e||!d||[d.weight,d.reps,d.effort].some(v=>v===''||!Number.isFinite(num(v))||num(v)<0)||num(d.reps)<=0||num(d.effort)>10){state.voiceError='Completa carga, repeticiones y RIR entre 0 y 10.';break;}const target=state.exercises[e.exercise]?.sets.find(s=>s.id===e.set);if(!target){state.voiceError='La serie ya no está disponible.';break;}e.previous=e.weight+' kg × '+e.reps+' · RIR '+(e.effort||'—');Object.assign(e,{weight:d.weight,reps:d.reps,effort:d.effort,version:e.version+1,status:'registered'});Object.assign(target,{weight:e.weight,value:e.reps,effort:num(e.effort),status:'done'});state.sheet=null;notify('Registro confirmado. Se actualiza la misma serie.');break;}
 case 'v2-voice-history':state.sheet='voice-audit';state.voiceEdit=Number(d.id);break;
 case 'v2-voice-example':if(!state.voicePaused){state.voiceEvents.push({id:Date.now(),time:clock(state.elapsed),said:'Registrar cien kilos, ocho repeticiones, RIR dos',weight:'100',reps:'8',effort:'2',status:'review',set:state.selected,exercise:state.ex,version:1});state.voiceFilter='all';}break;
 case 'v2-capture':case 'capture':state.fullSurface='capture';state.framing??='ok';state.spokenGuide??=false;state.recording=false;break;
 case 'v2-framing':state.framing=d.value;if(state.spokenGuide)speakGuide();break;
 case 'v2-guide-toggle':state.spokenGuide=!state.spokenGuide;if(state.spokenGuide)speakGuide();else if('speechSynthesis' in window)speechSynthesis.cancel();break;
 case 'v2-guide-speak':speakGuide();return false;
 case 'v2-capture-voice':if(state.voice&&state.voicePaused)state.voicePaused=false;else if(state.voice)state.voice=false;else {state.voiceReturn='capture';state.voiceStep='choices';state.voiceVerified=false;state.sheet='voice';}break;
 case 'v2-command-start':if(!state.voice||state.voicePaused)return false;if(!state.recording)startCapture();break;
 case 'v2-command-stop':if(!state.voice||state.voicePaused)return false;if(state.recording)stopCapture();break;
 case 'v2-capture-start':if(state.recording)stopCapture();else startCapture();break;
 case 'phase':if(d.phase==='rest'){old.action(action,d,el);rr().presentation='card';break;}return old.action(action,d,el);
 default:return old.action(action,d,el);
 }return true;
};
function startCapture(){if((state.framing||'ok')!=='ok'){state.captureAttempted=true;if(state.spokenGuide)speakGuide();return;}state.captureAttempted=false;state.recording=true;}
function stopCapture(){state.recording=false;state.captured++;state.fullSurface='analysis';state.analysisTab='replay';state.analysisPlaying=false;}
function speakGuide(){if('speechSynthesis' in window){speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(framingMessages[state.framing||'ok']);utterance.lang='es-ES';utterance.rate=.95;speechSynthesis.speak(utterance);}}
document.addEventListener('input',event=>{const el=event.target,key=el.dataset.v2;if(!key)return;const value=el.value;if(key==='quality'){state.feedbackDraft.quality=Number(value);$$('.v2-feedback-score strong').forEach(e=>e.innerHTML=value+'<small>/10</small>');}
 else if(key.startsWith('tag-'))state.tagForm[key.slice(4)]=value;
 else if(key.startsWith('config-')){state.configDraft[key.slice(7)]=value;state.configDirty=true;}
 else if(key==='replace-search'){state.replaceSearch=value;const q=value.toLowerCase();$$('.v2-replacements>button').forEach(b=>b.hidden=!b.textContent.toLowerCase().includes(q));}
 else if(key==='analysis-frame'){state.analysisFrame=Number(value);state.analysisRep=Math.min(10,Math.floor(Number(value)/10)+1);state.analysisPlaying=false;updateAnalysis();}
 else if(key.startsWith('voice-')&&state.voiceEditDraft)state.voiceEditDraft[key.slice(6)]=value;
 else if(key.startsWith('super-'))state.superDraft={...(state.superDraft||{}),[key.slice(6)]:value};
 else state[key]=value;
});
const panelContent=sheetContent;sheetContent=function(id){if(id==='voice-audit'){const e=state.voiceEvents.find(e=>e.id===state.voiceEdit);return `<p class="sheet-subtitle">La transcripción original se conserva.</p><div class="v2-history-note"><small>ORIGINAL</small><p>«${esc(e?.said)}»</p></div><div class="v2-history-note"><small>VALOR ANTERIOR</small><strong>${esc(e?.previous)}</strong></div><div class="v2-history-note"><small>ACTUAL · V${e?.version}</small><strong>${e?.weight} kg × ${e?.reps} · RIR ${e?.effort}</strong></div>`;}return panelContent(id);};
// Refresh scenario controls after extending the fixture catalogue.
$('#scene-select').innerHTML='';for(const group of [...new Set(scenarios.map(s=>s[2]))]){const opt=document.createElement('optgroup');opt.label=group;scenarios.filter(s=>s[2]===group).forEach(([id,label])=>{const o=document.createElement('option');o.value=id;o.textContent=label;opt.append(o);});$('#scene-select').append(opt);}
descriptions.cards={title:'Siempre la misma tarjeta.',text:'Una serie, un marco estable. El detalle se abre fuera de la tarjeta.',gain:'Dimensiones idénticas en todos los estados. Ningún contenido requiere desplazamiento interno.',watch:'Compara el registro, técnicas, movilidad, descanso y medios en pantalla compacta y con texto aumentado.'};
descriptions.list={title:'Registra donde está la serie.',text:'Cada fila pertenece a un ejercicio y conserva su contexto. Un acordeón abre el detalle.',gain:'Registro en cada serie, preparación compacta y superseries organizadas por ronda.',watch:'Puedes comparar el registro por fila con la variante que conserva el roadmap inferior.'};
loadScenario(params.get('scene')||'strength');
setInterval(()=>{updateEclipse();if(state.phase==='rest'&&rr().seconds<=0&&state.restPanel==='game'){state.restPanel='clock';window.KpknArcade?.stop();render();}if(state.analysisPlaying&&state.fullSurface==='analysis'){state.analysisFrame=(state.analysisFrame+1)%101;state.analysisRep=Math.min(10,Math.floor(state.analysisFrame/10)+1);$$('[data-v2="analysis-frame"]').forEach(i=>i.value=state.analysisFrame);updateAnalysis();}},100);
window.KpknPrototypeV2={getRest:()=>({seconds:rr().seconds,running:rr().running,active:rr().active}),getGame:()=>({mode:state.arcadeMode,visible:state.phase==='rest'&&state.restPanel==='game'}),reduced:()=>reduced};
})();
